function validateTripTimes(v,old={}){const startDate=v.data??old.data,startTime=v.hora??old.hora,endDate=v.data_fim??old.data_fim,endTime=v.hora_fim??old.hora_fim;if(!endDate||!endTime)throw Error('Informe a data e a hora de conclusão da viagem.');const start=new Date(startDate+'T'+startTime),end=new Date(endDate+'T'+endTime);if(!Number.isFinite(start.getTime())||!Number.isFinite(end.getTime()))throw Error('Confira as datas e os horários da viagem.');if(end<start)throw Error('A conclusão não pode ocorrer antes do início da viagem.');}
