function driverVehicleMetrics(trips){const groups=new Map();for(const v of trips){if(noRevenue(v)||!(+v.valor>0))continue;const key=JSON.stringify([v.motorista_id]);if(!groups.has(key))groups.set(key,{motorista_id:v.motorista_id,receita:0,km:0});const g=groups.get(key);g.receita+=+v.valor;g.km+=revenueKm(v);}return [...groups.values()].map(g=>({...g,porKm:g.km>0?g.receita/g.km:null})).sort((a,b)=>(b.porKm??-1)-(a.porKm??-1));}
