 '<div class="panel">'+(cars.map(car=>{const list=items.filter(t=>t.veiculo_id===car.id),carExpenses=costs.filter(e=>e.veiculo_id===car.id),totalKm=list.reduce((a,t)=>a+tripKm(t),0),revenue=sum(list),cost=sum(carExpenses);return row([car.modelo,car.placa].filter(Boolean).join(' · '),'KM: '+totalKm.toLocaleString('pt-BR')+' · Receita: '+money(revenue)+' · Despesas: '+money(cost),money(revenue-cost),'',category);}).join('')||'<div class="empty">Nenhum veículo nesta categoria.</div>')+'</div>';
